/*
 Problem: 3116. Kth Smallest Amount With Single Denomination Combination
 Language: cpp
 Runtime: 183 ms (13.57%)
 Memory: 20.6 MB (86.22%)
 Tags: Array, Math, Binary Search, Bit Manipulation, Combinatorics, Number Theory
*/
class Solution {
public:
    long long findKthSmallest(vector<int>& coins, int k) {
        long long lo = 1, hi = 1LL * (*min_element(coins.begin(), coins.end())) * k;

        auto count = [&](long long x) {
            long long res = 0;
            int n = coins.size();

            for (int mask = 1; mask < (1 << n); ++mask) {
                long long lcm = 1;
                int bits = 0;
                bool ok = true;

                for (int i = 0; i < n; ++i) {
                    if (mask >> i & 1) {
                        ++bits;

                        long long g = gcd(lcm, 1LL * coins[i]);
                        lcm = lcm / g * coins[i];

                        if (lcm > x) {
                            ok = false;
                            break;
                        }
                    }
                }

                if (!ok) continue;

                long long cnt = x / lcm;

                if (bits & 1)
                    res += cnt;
                else
                    res -= cnt;
            }

            return res;
        };

        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;

            if (count(mid) >= k)
                hi = mid;
            else
                lo = mid + 1;
        }

        return lo;
    }
};
